using Microsoft.AspNetCore.Mvc;using Microsoft.Extensions.Localization;using MiniStore.Application.DTOs.Purchases;using MiniStore.Application.Services;using MiniStore.Web.Authorization;
namespace MiniStore.Web.Controllers;
public sealed class PurchaseAgreementsController(PurchaseAgreementService service,IStringLocalizer<SharedResource> localizer):Controller
{
 [HttpGet,PermissionAuthorize("PurchaseAgreements.View")]public async Task<IActionResult>Index()=>View(await service.GetAllAsync());
 [HttpGet,PermissionAuthorize("PurchaseAgreements.Create")]public async Task<IActionResult>Create(int sourcingEventId)=>View(await service.GetCreatePageAsync(sourcingEventId));
 [HttpPost,ValidateAntiForgeryToken,PermissionAuthorize("PurchaseAgreements.Create")]public async Task<IActionResult>Create(CreatePurchaseAgreementDto dto){try{var id=await service.CreateAsync(dto);Notify("success","Purchase agreement created.");return RedirectToAction(nameof(Details),new{id});}catch(Exception e)when(e is ArgumentException or InvalidOperationException){Notify("danger",e.Message);return RedirectToAction("Comparison","SupplierQuotations",new{sourcingEventId=dto.SourcingEventId});}}
 [HttpGet,PermissionAuthorize("PurchaseAgreements.View")]public async Task<IActionResult>Details(int id){var value=await service.GetAsync(id);return value is null?NotFound():View(value);}
 [HttpPost,ValidateAntiForgeryToken,PermissionAuthorize("PurchaseAgreements.Activate")]public async Task<IActionResult>Activate(int id,byte[] rowVersion){await service.ActivateAsync(id,rowVersion);Notify("success","Purchase agreement activated.");return RedirectToAction(nameof(Details),new{id});}
 [HttpPost,ValidateAntiForgeryToken,PermissionAuthorize("PurchaseAgreements.Cancel")]public async Task<IActionResult>Cancel(int id,string reason,byte[] rowVersion){await service.CancelAsync(id,reason,rowVersion);Notify("success","Purchase agreement cancelled.");return RedirectToAction(nameof(Details),new{id});}
 [HttpPost,ValidateAntiForgeryToken,PermissionAuthorize("PurchaseAgreements.Release")]public async Task<IActionResult>Release(ReleasePurchaseAgreementDto dto){try{var id=await service.ReleaseAsync(dto);Notify("success","Purchase order draft released from agreement.");return RedirectToAction("Details","PurchaseOrders",new{id});}catch(Exception e)when(e is ArgumentException or InvalidOperationException){Notify("danger",e.Message);return RedirectToAction(nameof(Details),new{id=dto.AgreementId});}}
 private void Notify(string type,string message){TempData["NotificationType"]=type;TempData["NotificationMessage"]=localizer[message].Value;}
}
